00076 Area MCTSHelper::getTileAreaRestricted( const Area& tileArea, const int offLT, const int offRB )
00077 {
00078   return Area( tileArea.x + offLT, tileArea.y + offLT, tileArea.width - ( offLT + offRB ), tileArea.height - ( offLT + offRB ) );
00079 }
00080 
00081 void MCTSHelper::clipMvToArea( Mv& rcMv, const Area& block, const Area& clipArea, const SPS& sps, const int mvFracBits )
00082 {
00083   const int iHorMax = ( clipArea.x + clipArea.width - (int)block.x - (int)block.width ) << mvFracBits;
00084   const int iHorMin = ( clipArea.x - (int)block.x ) << mvFracBits;
00085 
00086   const int iVerMax = ( clipArea.y + clipArea.height - (int)block.y - (int)block.height ) << mvFracBits;
00087   const int iVerMin = ( clipArea.y - (int)block.y ) << mvFracBits;
00088 
00089   rcMv.setHor( Clip3( iHorMin, iHorMax, rcMv.getHor() ) );
00090   rcMv.setVer( Clip3( iVerMin, iVerMax, rcMv.getVer() ) );
00091 }
00092 
00093 Area MCTSHelper::getTileArea( const CodingStructure* cs, const int ctuAddr )
00094 {
00095   const PPS *pps = cs->pps;
00096   const int  maxCUWidth  = cs->pcv->maxCUWidth;
00097   const int  maxCUHeight = cs->pcv->maxCUHeight;
00098 
00099   const uint32_t tileIdx = pps->getTileIdx( (uint32_t)ctuAddr );
00100   const uint32_t tileX = tileIdx % pps->getNumTileColumns();
00101   const uint32_t tileY = tileIdx / pps->getNumTileColumns();
00102 
00103   const int tileWidthtInCtus = pps->getTileColumnWidth( tileX );
00104   const int tileHeightInCtus = pps->getTileRowHeight  ( tileY );
00105   const int tileXPosInCtus   = pps->getTileColumnBd( tileX );
00106   const int tileYPosInCtus   = pps->getTileRowBd( tileY );
00107 
00108   const int tileLeftTopPelPosX = maxCUWidth * tileXPosInCtus;
00109   const int tileLeftTopPelPosY = maxCUHeight * tileYPosInCtus;
00110   const int tileRightBottomPelPosX = std::min<int>( ( ( tileWidthtInCtus + tileXPosInCtus ) * maxCUWidth ), (int)cs->picture->lwidth() ) - 1;
00111   const int tileRightBottomPelPosY = std::min<int>( ( ( tileHeightInCtus + tileYPosInCtus ) * maxCUHeight ), (int)cs->picture->lheight() ) - 1;
00112 
00113   return Area( tileLeftTopPelPosX, tileLeftTopPelPosY, tileRightBottomPelPosX - tileLeftTopPelPosX + 1, tileRightBottomPelPosY - tileLeftTopPelPosY + 1 );
00114 }
00115 
00116 bool MCTSHelper::isRefBlockAtRestrictedTileBoundary( const PredictionUnit &pu )
00117 {
00118   const Area& tileArea = pu.cs->picture->mctsInfo.getTileArea();
00119   const int mvPrecBits = MV_FRACTIONAL_BITS_INTERNAL;
00120 
00121   for( int refList = 0; refList < NUM_REF_PIC_LIST_01; refList++ )
00122   {
00123     if( pu.refIdx[refList] >= 0 )
00124     {
00125       const Mv& mv = pu.mv[refList];
00126       Area targetBlock( pu.Y().offset( mv.getHor() >> mvPrecBits, mv.getVer() >> mvPrecBits ), pu.Y().size() );
00127       // NOTE: at boundary take sub-pel filter samples into account
00128       if(
00129         targetBlock.x < tileArea.x + 3 ||
00130         targetBlock.y < tileArea.y + 3 ||
00131         targetBlock.bottomRight().x > tileArea.bottomRight().x - 4 ||
00132         targetBlock.bottomRight().y > tileArea.bottomRight().y - 4 )
00133       {
00134         return true;
00135       }
00136     }
00137   }
00138   return false;
00139 }
00140 
00141 static void getMotInfoBlockPartPos( const PredictionUnit& pu, int xOff, int yOff, const Mv& mv, int& ruiPredXLeft, int& ruiPredYTop, int& ruiPredXRight, int& ruiPredYBottom )
00142 {
00143   const int mvFracBits = MV_FRACTIONAL_BITS_INTERNAL;
00144 
00145   ruiPredXLeft   = ( mv.getHor() >> mvFracBits ) + pu.lx() + xOff;
00146   ruiPredYTop    = ( mv.getVer() >> mvFracBits ) + pu.ly() + yOff;
00147   ruiPredXRight  = ruiPredXLeft + ( 1 << g_miScaling.posx ) - 1;
00148   ruiPredYBottom = ruiPredYTop + ( 1 << g_miScaling.posy ) - 1;
00149 }
00150 
00151 static bool checkMVRange( const Mv& mv, const Area& tileArea, int predXLeft, int predXRight, int predYTop, int predYBottom, ChromaFormat chromaFormat, bool isLuma, bool msgFlag )
00152 {
00153   // Filter length of sub-sample generation filter to be considered
00154   int sampleOffsetLT, sampleOffsetRB, fracDiv;
00155 
00156   if( isLuma )
00157   {
00158     sampleOffsetLT = 3;
00159     sampleOffsetRB = 4;
00160     fracDiv = 1 << MV_FRACTIONAL_BITS_INTERNAL;
00161   }
00162   else
00163   {
00164     sampleOffsetLT = 2; //1; // 2 in luma coordinates!
00165     sampleOffsetRB = 3; //2; // 3 in luma coordinates!
00166     fracDiv = 1 << ( MV_FRACTIONAL_BITS_INTERNAL + 1 );
00167   }
00168 
00169   const int leftTopPelPosX = tileArea.topLeft().x;
00170   const int leftTopPelPosY = tileArea.topLeft().y;
00171   const int rightBottomPelPosX = tileArea.bottomRight().x;
00172   const int rightBottomPelPosY = tileArea.bottomRight().y;
00173 
00174   const bool isFullPelHor = ( mv.getHor() % fracDiv == 0 );
00175   const bool isFullPelVer = ( mv.getVer() % fracDiv == 0 );
00176 
00177   const int rangeXLeft   = leftTopPelPosX + ( isFullPelHor ? 0 : sampleOffsetLT );
00178   const int rangeYTop    = leftTopPelPosY + ( isFullPelVer ? 0 : sampleOffsetLT );
00179   const int rangeXRight  = rightBottomPelPosX - ( isFullPelHor ? 0 : sampleOffsetRB );
00180   const int rangeYBottom = rightBottomPelPosY - ( isFullPelVer ? 0 : sampleOffsetRB );
00181 
00182   if( !( predXLeft >= rangeXLeft && predXLeft <= rangeXRight ) || !( predXRight >= rangeXLeft && predXRight <= rangeXRight ) )
00183   {
00184     if( msgFlag )
00185     {
00186       msg( WARNING, "%s: pu motion vector across tile boundaries MV(%d,%d) RangeLR(%d,%d) PredLR(%d,%d)\n", (isLuma ? "LUMA": "CHROMA"), mv.getHor(), mv.getVer(), rangeXLeft, rangeXRight, predXLeft, predXRight );
00187     }
00188     return false;
00189   }
00190   else if( !( predYTop >= rangeYTop && predYTop <= rangeYBottom ) || !( predYBottom >= rangeYTop && predYBottom <= rangeYBottom ) )
00191   {
00192     if( msgFlag )
00193     {
00194       msg( WARNING, "%s: pu motion vector across tile boundaries MV(%d,%d) RangeTB(%d,%d) PredTB(%d,%d)\n", (isLuma ? "LUMA" : "CHROMA"), mv.getHor(), mv.getVer(), rangeYTop, rangeYBottom, predYTop, predYBottom );
00195     }
00196     return false;
00197   }
00198 
00199   return true;
00200 }
00201 
00202 bool MCTSHelper::checkMvBufferForMCTSConstraint( const PredictionUnit &pu, bool msgFlag )
00203 {
00204   const Area& tileArea = pu.cs->picture->mctsInfo.getTileArea();
00205   const ChromaFormat chromaFormat = pu.cs->sps->getChromaFormatIdc();
00206 
00207   CMotionBuf mb = pu.getMotionBuf();
00208 
00209   const int blkW = 1 << ( g_miScaling.posx );
00210   const int blkH = 1 << ( g_miScaling.posy );
00211 
00212   for( int y = 0; y < mb.height; y++ )
00213   {
00214     for( int x = 0; x < mb.width; x++ )
00215     {
00216       const MotionInfo &mi = mb.at( x, y );
00217       int xOff = x << g_miScaling.posx;
00218       int yOff = y << g_miScaling.posy;
00219 
00220       for( int refList = 0; refList < NUM_REF_PIC_LIST_01; refList++ )
00221       {
00222         if( pu.refIdx[refList] >= 0 || mi.refIdx[refList] >= 0 )
00223         {
00224           const Mv& mv = mi.mv[refList];
00225           int predXLeft, predYTop, predXRight, predYBottom;
00226           getMotInfoBlockPartPos( pu, xOff, yOff, mv, predXLeft, predYTop, predXRight, predYBottom );
00227           if( !checkMVRange( mv, tileArea, predXLeft, predXRight, predYTop, predYBottom, chromaFormat, true, msgFlag ) )
00228           {
00229             return false;
00230           }
00231 
00232           // Chroma
00233           if( !pu.cu->affine )
00234           {
00235             if( !checkMVRange( mv, tileArea, predXLeft, predXRight, predYTop, predYBottom, chromaFormat, false, msgFlag ) )
00236             {
00237               return false;
00238             }
00239           }
00240           else
00241           {
00242             if( x % 2 == 0 && y % 2 == 0 )
00243             {
00244               const MotionInfo &miA = mi;
00245               const MotionInfo &miB = mb.at( x + 1, y + 1 );
00246               Mv mvAff = miA.mv[refList] + miB.mv[refList];
00247               roundAffineMv( mvAff.hor, mvAff.ver, 1 );
00248               getMotInfoBlockPartPos( pu, xOff, yOff, mvAff, predXLeft, predYTop, predXRight, predYBottom );
00249               if( !checkMVRange( mvAff, tileArea, predXLeft, predXRight + blkW, predYTop, predYBottom + blkH, chromaFormat, false, msgFlag ) )
00250               {
00251                 return false;
00252               }
00253             }
00254           }
00255         }
00256       }
00257     }
00258   }
00259 
00260   return true;
00261 }
00262 bool MCTSHelper::checkMvIsNotInRestrictedArea( const PredictionUnit &pu, const Mv& mv, const Area& restrArea, const MvPrecision mvPrec )
00263 {
00264   CHECKD( mvPrec < MV_PRECISION_INT, "Wrong MV precision!" );
00265   Mv testMv = mv;
00266   testMv >>= mvPrec - MV_PRECISION_INT;
00267   Area targetArea = pu.Y();
00268   targetArea.repositionTo( targetArea.offset( testMv.getHor(), testMv.getVer() ) );
00269   if( !restrArea.contains( targetArea ) )
00270   {
00271     // Skip this pos
00272     return false;
00273   }
00274   return true;
00275 }
00276 bool MCTSHelper::checkMvForMCTSConstraint( const PredictionUnit &pu, const Mv& mv, const MvPrecision mvPrec )
00277 {
00278   return checkMvIsNotInRestrictedArea( pu, mv, pu.cs->picture->mctsInfo.getTileAreaSubPelRestricted( pu ), mvPrec );
00279 }
